                js: "const shader = await Shader.fetch([\n    \"sdf2d/circle\",\n    \"sdf2d/box\",\n    \"sdf2d/star\",\n    \"sdf/op_smooth_union\",\n    \"map/rotate2\",\n    SHADER,\n]);\nshader.set(\"u.blend\", 0.12);\nshader.set(\"u.rings\", 20);\nshader.set(\"u.glow\", 10);\nshader.set(\"u.inside_color\", [1, 0, 0.514]);\nshader.set(\"u.rim_color\", [0.514, 0, 1]);\nshader.set(\"u.outside_color\", [0, 0.514, 1]);",
                py: "shader = Shader([\n    \"sdf2d/circle\",\n    \"sdf2d/box\",\n    \"sdf2d/star\",\n    \"sdf/op_smooth_union\",\n    \"map/rotate2\",\n    SHADER,\n])\nshader.set(\"u.blend\", 0.12)\nshader.set(\"u.rings\", 20.0)\nshader.set(\"u.glow\", 10.0)\nshader.set(\"u.inside_color\", [1.0, 0.0, 0.514])\nshader.set(\"u.rim_color\", [0.514, 0.0, 1.0])\nshader.set(\"u.outside_color\", [0.0, 0.514, 1.0])",
                swift: "let shader = try Shader([\n    \"sdf2d/circle\",\n    \"sdf2d/box\",\n    \"sdf2d/star\",\n    \"sdf/op_smooth_union\",\n    \"map/rotate2\",\n    SHADER,\n])\ntry shader.set(\"u.blend\", 0.12)\ntry shader.set(\"u.rings\", 20.0)\ntry shader.set(\"u.glow\", 10.0)\ntry shader.set(\"u.inside_color\", [1.0, 0.0, 0.514])\ntry shader.set(\"u.rim_color\", [0.514, 0.0, 1.0])\ntry shader.set(\"u.outside_color\", [0.0, 0.514, 1.0])",
